/**
 * Full bucket data structure
 * Contains all bucket information from API
 */
export interface Bucket {
  bucketId: string;
  address: string;
  marginType: string; // e.g., "cross", "isolated"
  collateralAsset: string; // e.g., "USDC"
  depositedMargin: number; // Total margin deposited
  totalEquity: number;
  availableMargin: number;
  usedMargin: number;
  unrealizedProfit: number;
  unrealizedLoss: number;
  realizedProfit: number;
  realizedLoss: number;
  unrealizedPnL: number; // Calculated: unrealizedProfit - unrealizedLoss
  marginRatio: number;
  imr: number; // Initial Margin Requirement (as number, e.g., 10 for 10%)
  totalNotionalValue: number;
  riskLevel: string;
  maxLeverage: number;
  correlationOffset: number;
  status: string; // e.g., "dormant", "active"
  createdAt: string; // ISO timestamp string
  updatedAt: string; // ISO timestamp string
  // Legacy/computed fields for backward compatibility
  leverage: number; // Alias for maxLeverage
  marginMode: string; // Alias for marginType
  raw: any;
}

