/**
 * Recent trade data for display in trade table
 */
export interface RecentTradeDos {
  time: number;
  size: number;
  price: number;
  is_buyer_maker: boolean;
}

/**
 * Transform RawTrade array to RecentTradeDos array for display
 * Converts satoshi strings to decimal numbers and normalizes timestamps
 * Sorts trades by timestamp descending (newest first)
 * This is a pure function with no dependencies, suitable for use outside React hooks
 */
export function transformRawTradesToRecentTradeDos(
  rawTrades: RawTrade[],
): RecentTradeDos[] {
  if (!rawTrades || !Array.isArray(rawTrades) || rawTrades.length === 0) {
    return [];
  }

  // Sort by timestamp descending (newest first)
  const sortedTrades = [...rawTrades].sort((a, b) => {
    const timeA = normalizeTimestamp(a.timestamp);
    const timeB = normalizeTimestamp(b.timestamp);
    return timeB - timeA; // Descending: newest first
  });

  // Convert to display format
  return sortedTrades.map((trade: RawTrade): RecentTradeDos => {
    // Handle timestamp - convert string to number and ensure milliseconds
    const timestamp = normalizeTimestamp(
      trade.timestamp as string | number,
    );

    // Convert satoshi strings to decimal numbers
    const size: number = toNumberFromSatoshi(trade.quantity);
    const price: number = toNumberFromSatoshi(trade.price);

    return {
      time: timestamp,
      size,
      price,
      // is_buyer_maker is not in RawTrade interface, default to false
      // If needed, this should come from WebSocket data or be calculated from buy_address/sell_address
      is_buyer_maker: false,
    };
  });
}

