/**
 * Transform API/WS response to Position format
 * Converts Satoshi strings to decimal numbers for display
 * Handles both RawPosition (from HTTP API) and MultiFeedPositionsData (from WebSocket)
 * This is a pure function with no dependencies, suitable for use outside React hooks
 */
export function transformPosition(
  pos: RawPosition | MultiFeedPositionsData,
): Position {
  // Normalize position data - handle both RawPosition and MultiFeedPositionsData
  // positionId is required, so generate a fallback if missing
  let positionId: string;
  if ("position_id" in pos && pos.position_id) {
    // RawPosition always has position_id
    positionId = pos.position_id;
  } else if (
    "position_id" in pos &&
    (pos as MultiFeedPositionsData).position_id
  ) {
    // MultiFeedPositionsData might have position_id
    positionId = (pos as MultiFeedPositionsData).position_id!;
  } else {
    // Generate fallback ID if missing (for WebSocket updates without position_id)
    positionId = `${pos.market_id}-${pos.bucket_id || "default"}-${pos.address}`;
  }

  // Get entry price - RawPosition uses average_entry_price, MultiFeedPositionsData uses entry_price
  const entryPriceStr =
    "average_entry_price" in pos
      ? pos.average_entry_price
      : pos.entry_price;

  // Get side - RawPosition uses side (string), MultiFeedPositionsData uses position_side
  let side: "LONG" | "SHORT";
  if ("position_side" in pos && pos.position_side) {
    // MultiFeedPositionsData format
    side = pos.position_side;
  } else if ("side" in pos && pos.side) {
    // RawPosition format: "SIDE_BUY" (long) or "SIDE_SELL" (short)
    side =
      pos.side === "SIDE_BUY" || pos.side.toUpperCase().includes("BUY")
        ? ORDER_SIDE_LONG
        : ORDER_SIDE_SHORT;
  } else {
    // Fallback: infer from size sign
    const size = toNumberFromSatoshi(pos.size);
    side = size >= 0 ? ORDER_SIDE_LONG : ORDER_SIDE_SHORT;
  }

  // Convert size
  const size = toNumberFromSatoshi(pos.size);

  // Convert numeric fields from Satoshi strings to decimals
  const entryPrice = toNumberFromSatoshi(entryPriceStr);
  const markPrice = toNumberFromSatoshi(pos.mark_price);
  const leverage = pos.leverage
    ? toNumberFromSatoshi(pos.leverage)
    : 0;

  // Calculate unrealized PnL from API format (unrealized_profit - unrealized_loss)
  // or use legacy format (unrealized_pnl) if new fields are not available
  // Use BigInt for precision during subtraction
  let unrealizedPnL = 0;
  if (
    pos.unrealized_profit !== undefined ||
    pos.unrealized_loss !== undefined
  ) {
    // New API format: separate profit and loss fields
    // Use BigInt for precise subtraction
    const profitBigInt = toBigInt(pos.unrealized_profit);
    const lossBigInt = toBigInt(pos.unrealized_loss);
    const pnlBigInt = profitBigInt - lossBigInt;
    // Convert BigInt result to decimal using utility function for consistency
    unrealizedPnL = toNumberFromSatoshi(pnlBigInt.toString());
  } else if ("unrealized_pnl" in pos && pos.unrealized_pnl !== undefined) {
    // Legacy format: single unrealized_pnl field (only in RawPosition)
    unrealizedPnL = toNumberFromSatoshi(pos.unrealized_pnl);
  }

  // Calculate margin (margin_balance from API or calculate: size * entryPrice / leverage)
  const marginBalance = toNumberFromSatoshi(pos.margin_balance);
  const margin =
    marginBalance ||
    (leverage && entryPrice && size !== 0
      ? Math.abs((Math.abs(size) * entryPrice) / leverage)
      : 0);

  // Get margin mode - RawPosition has margin_mode/margin_type, MultiFeedPositionsData might not
  const marginMode =
    ("margin_mode" in pos && pos.margin_mode) ||
    ("margin_type" in pos && pos.margin_type) ||
    MARGIN_MODE_CROSS;

  return {
    positionId,
    marketId: pos.market_id.toString(),
    symbol: pos.symbol || `m-${pos.market_id}`,
    size: Math.abs(size),
    entryPrice,
    markPrice,
    liquidationPrice: pos.liquidation_price
      ? toNumberFromSatoshi(pos.liquidation_price)
      : 0,
    unrealizedPnL,
    leverage,
    margin,
    side,
    marginMode,
    bucketId: pos.bucket_id ? String(pos.bucket_id) : "",
    raw: pos,
  };
}

/**
 * Transform RawOrder from API/WS response to PendingOrder format
 * Handles RawOrder structure from API (snake_case with enum values and string numbers)
 * Based on RawOrder interface from src/sdk/types/api.ts
 * Requires order_id to be present (orders without order_id should be filtered before calling this)
 * This is a pure function with no dependencies, suitable for use outside React hooks
 */
export function transformRawOrderToPendingOrder(order: RawOrder): PendingOrder {
  // Normalize side enum: "ORDER_SIDE_BUY" -> "BUY", "ORDER_SIDE_SELL" -> "SELL"
  const normalizedSide = order.side === "SIDE_BUY" ? "BUY" : "SELL";

  // Pass through type as-is (no transformation needed)
  // RawOrder.type is already OrderType: "ORDER_TYPE_LIMIT", "ORDER_TYPE_MARKET", etc.

  // Normalize status enum: "ORDER_STATUS_OPEN" -> "OPEN", etc.
  // RawOrder.status is OrderStatus type: "ORDER_STATUS_OPEN", "ORDER_STATUS_PARTIAL", "ORDER_STATUS_CANCELLED", etc.
  let normalizedStatus: string = order.status || "ORDER_STATUS_PENDING";
  if (normalizedStatus.includes("ORDER_STATUS_")) {
    normalizedStatus = normalizedStatus.replace("ORDER_STATUS_", "");
  }
  // Normalize timeInForce enum: "TIME_IN_FORCE_GTC" -> "GTC"
  // RawOrder.time_in_force is string like "TIME_IN_FORCE_GTC"
  const rawTimeInForce = order.time_in_force;
  let normalizedTimeInForce: string | undefined = rawTimeInForce;
  if (rawTimeInForce && rawTimeInForce.includes("TIME_IN_FORCE_")) {
    normalizedTimeInForce = rawTimeInForce.replace("TIME_IN_FORCE_", "");
  }

  // Convert string numbers to numbers
  // RawOrder has price, quantity, filled_quantity as strings (Satoshi format)
  // Use utility function from math.ts for consistent satoshi conversion
  const parseNumber = (value: string | number | undefined): number =>
    toNumberFromSatoshi(value);

  // Use RawOrder fields (snake_case)
  const quantity = parseNumber(order.quantity);
  const price = parseNumber(order.price);
  const filledQuantity = parseNumber(order.filled_quantity);
  const remainingQuantity = quantity - filledQuantity;

  // Convert timestamp to number (milliseconds)
  // RawOrder.timestamp can be Timestamp object (with seconds/nanos) or string/number
  // PendingOrder requires createdAt and updatedAt as numbers (not undefined)
  // Use normalizeProtobufTimestamp utility which handles all timestamp formats
  const timestamp = normalizeProtobufTimestamp(order.timestamp, Date.now());
  return {
    id: order.order_id,
    orderId: order.order_id,
    marketId: order.market_id || order.bucket_id,
    side: normalizedSide,
    type: order.type,
    quantity,
    price,
    filledQuantity,
    remainingQuantity,
    status: normalizedStatus,
    timeInForce: normalizedTimeInForce,
    createdAt: timestamp,
    updatedAt: timestamp, // Use same timestamp if updated_at is not available
    raw: order,
  };
}

