import { timestampToISOString } from "../utils/time";

/**
 * Convert MultiFeedBucketData to RawBucket format
 * MultiFeedBucketData has fewer fields, so we provide defaults for missing fields
 * This is a pure function with no dependencies, suitable for use outside React hooks
 * @param multiFeedBucket - MultiFeedBucketData from WebSocket subscription
 * @returns RawBucket object with all required fields
 */
export function convertMultiFeedToRawBucket(
  multiFeedBucket: MultiFeedBucketData,
): RawBucket {
  const now = new Date().toISOString();
  return {
    bucket_id: multiFeedBucket.bucket_id,
    address: multiFeedBucket.address,
    margin_type: multiFeedBucket.margin_type.toLowerCase(),
    collateral_asset: "USDC", // Default, not provided in MultiFeedBucketData
    deposited_margin: "0", // Default, not provided in MultiFeedBucketData
    total_equity: multiFeedBucket.total_equity,
    available_margin: multiFeedBucket.available_margin,
    used_margin: multiFeedBucket.used_margin,
    unrealized_profit: multiFeedBucket.unrealized_profit,
    unrealized_loss: multiFeedBucket.unrealized_loss, // Default, not provided in MultiFeedBucketData
    realized_profit: "0", // Default, not provided in MultiFeedBucketData
    realized_loss: "0", // Default, not provided in MultiFeedBucketData
    margin_ratio: "0", // Default, not provided in MultiFeedBucketData
    imr: "0", // Default, not provided in MultiFeedBucketData
    total_notional_value: "0", // Default, not provided in MultiFeedBucketData
    risk_level: "low", // Default, not provided in MultiFeedBucketData
    max_leverage: "0", // Default, not provided in MultiFeedBucketData
    correlation_offset: 0, // Default, not provided in MultiFeedBucketData
    status: "active", // Default, not provided in MultiFeedBucketData
    created_at: now, // Default, not provided in MultiFeedBucketData
    updated_at: now, // Default, not provided in MultiFeedBucketData
  };
}

/**
 * Convert raw API bucket data (snake_case) to Bucket type
 * Handles conversion from satoshi strings to decimal numbers
 * @param rawBucket - Raw bucket data from API (snake_case format)
 * @returns Bucket object with all fields properly converted
 */
export function transformRawBucketToBucket(rawBucket: RawBucket): Bucket {
  // Extract bucketId from RawBucket (always snake_case)
  const bucketId = rawBucket.bucket_id || "---";

  // Calculate unrealized PnL using BigInt for precision
  // Convert satoshi strings to BigInt, subtract, then convert result to decimal
  const unrealizedProfitBigInt = toBigInt(rawBucket.unrealized_profit);
  const unrealizedLossBigInt = toBigInt(rawBucket.unrealized_loss);
  const unrealizedPnLBigInt = unrealizedProfitBigInt - unrealizedLossBigInt;

  // Convert BigInt result to decimal number using fromSatoshi (preserves precision)
  const unrealizedPnL = fromSatoshi(unrealizedPnLBigInt.toString());

  // Also convert individual profit/loss values for the Bucket interface
  const unrealizedProfit = toNumberFromSatoshi(rawBucket.unrealized_profit);
  const unrealizedLoss = toNumberFromSatoshi(rawBucket.unrealized_loss);

  // Parse max leverage - leverage values are not in satoshi format, they're decimal numbers
  // Uses utility function from math.ts for consistency
  const maxLeverage = parseNumericValue(rawBucket.max_leverage);

  return {
    bucketId,
    address: rawBucket.address || "",
    marginType: rawBucket.margin_type || "cross",
    collateralAsset: rawBucket.collateral_asset || "",
    depositedMargin: toNumberFromSatoshi(rawBucket.deposited_margin),
    totalEquity: toNumberFromSatoshi(rawBucket.total_equity),
    availableMargin: toNumberFromSatoshi(rawBucket.available_margin),
    usedMargin: toNumberFromSatoshi(rawBucket.used_margin),
    unrealizedProfit,
    unrealizedLoss,
    realizedProfit: toNumberFromSatoshi(rawBucket.realized_profit),
    realizedLoss: toNumberFromSatoshi(rawBucket.realized_loss),
    unrealizedPnL,
    marginRatio: toNumberFromSatoshi(rawBucket.margin_ratio),
    imr: toNumberFromSatoshi(rawBucket.imr), // IMR is not satoshi-scaled, it's a percentage
    totalNotionalValue: toNumberFromSatoshi(rawBucket.total_notional_value),
    riskLevel: rawBucket.risk_level || "",
    maxLeverage,
    correlationOffset: rawBucket.correlation_offset || 0,
    status: rawBucket.status || "",
    createdAt: timestampToISOString(rawBucket.created_at),
    updatedAt: timestampToISOString(rawBucket.updated_at),
    // Legacy/computed fields for backward compatibility
    leverage: maxLeverage,
    marginMode: rawBucket.margin_type || "cross",
    raw: rawBucket,
  };
}

/**
 * Calculate risk ratio for a bucket (used margin / total equity)
 * Returns a value between 0 and 1
 */
export function calculateRiskRatio(bucket: Bucket): number {
  return bucket.totalEquity > 0
    ? Math.min(Math.max(bucket.usedMargin / bucket.totalEquity, 0), 1)
    : 0;
}

/**
 * Calculate cross margin ratio for a bucket (used margin / total equity)
 */
export function calculateCrossMarginRatio(bucket: Bucket): number {
  return bucket.totalEquity > 0 ? bucket.usedMargin / bucket.totalEquity : 0;
}

/**
 * Get display margin type name from bucket
 */
export function getDisplayMarginType(bucket: Bucket): string {
  const marginTypeValue = bucket.marginMode || bucket.marginType || "cross";
  return marginTypeValue === "ISOLATED" || marginTypeValue === "isolated"
    ? "ISOLATED"
    : "CROSS";
}

// ============================================================================
// TYPE GUARDS
// ============================================================================

/**
 * Type guard to check if a bucket is RawBucket
 */
export function isRawBucket(
  bucket: RawBucket | MultiFeedBucketData,
): bucket is RawBucket {
  return "collateral_asset" in bucket;
}

/**
 * Type guard for LastPriceData
 */
export function isLastPriceData(value: any): value is LastPriceData {
  return (
    value !== null &&
    typeof value === "object" &&
    typeof value.price === "number" &&
    typeof value.market_id === "string" &&
    typeof value.quantity === "number" &&
    typeof value.timestamp === "number" &&
    typeof value.is_buyer_maker === "boolean" &&
    typeof value.trade_id === "string"
  );
}

/**
 * Type guard for MarkPriceData
 */
export function isMarkPriceData(value: any): value is MarkPriceData {
  return (
    value !== null &&
    typeof value === "object" &&
    typeof value.symbol === "string" &&
    typeof value.mark_price === "number" &&
    typeof value.timestamp === "number"
  );
}
